from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.3
.target sm_89
.address_size 64

.visible .entry conv2d_bf16(
    .param .u64 in_ptr,
    .param .u64 weight_ptr,
    .param .u64 out_ptr,
    .param .u32 total_elements
)
{
    .reg .pred %p<8>;
    .reg .u32  %r<64>;
    .reg .u64  %rd<32>;
    .reg .f32  %f<8>;
    .reg .b16  %h<8>;

    ld.param.u64 %rd1, [in_ptr];
    ld.param.u64 %rd2, [weight_ptr];
    ld.param.u64 %rd3, [out_ptr];
    ld.param.u32 %r1,  [total_elements];

    cvta.to.global.u64 %rd1, %rd1;
    cvta.to.global.u64 %rd2, %rd2;
    cvta.to.global.u64 %rd3, %rd3;

    mov.u32 %r2, %ctaid.x;
    mov.u32 %r3, %ntid.x;
    mov.u32 %r4, %tid.x;
    mad.lo.s32 %r5, %r2, %r3, %r4;   // idx = blockIdx.x*blockDim.x+threadIdx.x

    mov.u32 %r6, %nctaid.x;
    mul.lo.s32 %r7, %r6, %r3;       // stride = gridDim.x*blockDim.x

LOOP_START:
    setp.ge.s32 %p1, %r5, %r1;
    @%p1 bra LOOP_END;

    mov.u32 %r10, %r5;              // idx copy for decoding

    rem.u32 %r11, %r10, 222;        // ow
    div.u32 %r10, %r10, 222;

    rem.u32 %r12, %r10, 222;        // oh
    div.u32 %r10, %r10, 222;

    rem.u32 %r13, %r10, 32;         // oc
    div.u32 %r10, %r10, 32;

    mov.u32 %r14, %r10;             // n

    mul.lo.s32 %r15, %r14, 3;       // n*3
    mul.lo.s32 %r16, %r13, 3;       // oc*3

    mov.f32 %f1, 0f00000000;        // sum = 0.0

    mov.u32 %r20, 0;                // ic = 0
IC_LOOP:
    setp.ge.s32 %p2, %r20, 3;
    @%p2 bra IC_END;

    add.s32 %r21, %r15, %r20;       // c_index = n*3+ic
    add.s32 %r22, %r16, %r20;       // oc*3+ic

    mov.u32 %r23, 0;                // kh = 0
KH_LOOP:
    setp.ge.s32 %p3, %r23, 3;
    @%p3 bra KH_END;

    add.s32 %r24, %r12, %r23;              // ih = oh+kh
    mad.lo.s32 %r25, %r21, 224, %r24;      // c_index*224+ih
    mad.lo.s32 %r26, %r22, 3, %r23;        // (oc*3+ic)*3+kh

    mov.u32 %r27, 0;                       // kw = 0
KW_LOOP:
    setp.ge.s32 %p4, %r27, 3;
    @%p4 bra KW_END;

    add.s32 %r28, %r11, %r27;              // iw = ow+kw
    mad.lo.s32 %r29, %r25, 224, %r28;      // input_offset
    mad.lo.s32 %r30, %r26, 3, %r27;        // weight_offset

    cvt.s64.s32 %rd10, %r29;
    shl.b64 %rd10, %rd10, 1;
    add.s64 %rd11, %rd1, %rd10;
    ld.global.b16 %h1, [%rd11];

    cvt.s64.s32 %rd12, %r30;
    shl.b64 %rd12, %rd12, 1;
    add.s64 %rd13, %rd2, %rd12;
    ld.global.b16 %h2, [%rd13];

    cvt.f32.bf16 %f2, %h1;
    cvt.f32.bf16 %f3, %h2;
    fma.rn.f32 %f1, %f2, %f3, %f1;

    add.s32 %r27, %r27, 1;
    bra KW_LOOP;
KW_END:

    add.s32 %r23, %r23, 1;
    bra KH_LOOP;
KH_END:

    add.s32 %r20, %r20, 1;
    bra IC_LOOP;
IC_END:

    mad.lo.s32 %r40, %r14, 32, %r13;    // n*32+oc
    mad.lo.s32 %r41, %r40, 222, %r12;   // *222+oh
    mad.lo.s32 %r42, %r41, 222, %r11;   // *222+ow

    cvt.s64.s32 %rd20, %r42;
    shl.b64 %rd20, %rd20, 1;
    add.s64 %rd21, %rd3, %rd20;

    cvt.rn.bf16.f32 %h3, %f1;
    st.global.b16 [%rd21], %h3;

    add.s32 %r5, %r5, %r7;
    bra LOOP_START;
LOOP_END:
    ret;
