    def forward(self, x):
        weight = self.conv1.weight  # (32, 3, 3, 3) bf16

        N, C_in, H_in, W_in = x.shape
        C_out = weight.shape[0]
        H_out = H_in - 2
        W_out = W_in - 2

        out = torch.empty((N, C_out, H_out, W_out), dtype=torch.bfloat16, device=x.device)

        total = N * C_out * H_out * W_out
        threads = 256
        blocks = (total + threads - 1) // threads

        module = _get_ptx_module()
        module.launch(
            "conv2d_bf16",
            grid=(blocks, 1, 1),
            block=(threads, 1, 1),
            arguments=[x, weight, out, u32(total)],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return out

